//! Export engine E1–E3 (API.md §2.3).
//!
//! Jobs are **in-memory only** (API.md E2, flagged §10): each job holds its
//! generated bytes, so a deactivation mid-export cannot invalidate work that
//! already started (FEATURES.md F9 "deactivate mid-export" edge case). Pro is
//! checked once at creation; the Pro check is deliberately *not* repeated on
//! status/content so already-started jobs still complete. New jobs need Pro.
//!
//! Filters reuse the C2 whitelist via [`crate::history::parse_query`], so
//! validation stays in one place (AGENTS.md §4.2).

use std::collections::HashMap;
use std::fmt::Write as _;
use std::sync::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use netwatch_common::ErrorCode;
use serde::Serialize;
use serde_json::{Map, Value, json};
use sqlx::QueryBuilder;
use sqlx::Row;
use sqlx::SqlitePool;

use crate::error::ApiError;
use crate::history::ConnectionsQuery;
use crate::ratelimit::RateLimiter;

/// Job lifetime (API.md E1 `expires_in_s`, FEATURES.md F9 edge case).
const TTL: Duration = Duration::from_secs(600);

/// Filter whitelist — identical to C2 (API.md §2.3 / §2.2).
const FILTER_KEYS: &[&str] = &[
    "app_id",
    "app_name",
    "open",
    "protocol",
    "interface_id",
    "since",
    "until",
    "remote_ip",
    "remote_host",
    "remote_port",
];

/// Ordered columns for `connections` exports (DATABASE.md §2.4).
const CONNECTIONS_COLUMNS: &[&str] = &[
    "id",
    "app_id",
    "interface_id",
    "pid",
    "process_name",
    "protocol",
    "local_ip",
    "local_port",
    "remote_ip",
    "remote_port",
    "remote_host",
    "bytes_up",
    "bytes_down",
    "packets_up",
    "packets_down",
    "first_seen_at",
    "last_seen_at",
    "is_open",
];

/// Ordered columns for usage exports (DATABASE.md §2.5).
const USAGE_COLUMNS: &[&str] = &[
    "app_id",
    "bucket_start",
    "bytes_up",
    "bytes_down",
    "connection_count",
];

// ---------------------------------------------------------------------------
// Request parsing
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Scope {
    Connections,
    UsageHourly,
    UsageDaily,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Format {
    Csv,
    Json,
}

impl Format {
    fn content_type(self) -> &'static str {
        match self {
            Self::Csv => "text/csv; charset=utf-8",
            Self::Json => "application/json",
        }
    }

    fn extension(self) -> &'static str {
        match self {
            Self::Csv => "csv",
            Self::Json => "json",
        }
    }
}

#[derive(Debug)]
struct ParsedRequest {
    scope: Scope,
    format: Format,
    query: ConnectionsQuery,
}

/// Parse and validate an E1 request body.
///
/// # Errors
///
/// `QUERY_INVALID` for malformed JSON, unknown scope/format/filter keys,
/// empty filters, or invalid filter values (via the C2 parser).
fn parse_request(body: &[u8]) -> Result<ParsedRequest, ApiError> {
    let value: Value = serde_json::from_slice(body)
        .map_err(|_| ApiError::query_invalid("Request body must be JSON"))?;

    let scope = match value.get("scope").and_then(Value::as_str) {
        Some("connections") => Scope::Connections,
        Some("usage_hourly") => Scope::UsageHourly,
        Some("usage_daily") => Scope::UsageDaily,
        Some(other) => return Err(ApiError::query_invalid(format!("unknown scope: {other}"))),
        None => return Err(ApiError::query_invalid("missing scope")),
    };
    let format = match value.get("format").and_then(Value::as_str) {
        Some("csv") => Format::Csv,
        Some("json") => Format::Json,
        Some(other) => return Err(ApiError::query_invalid(format!("unknown format: {other}"))),
        None => return Err(ApiError::query_invalid("missing format")),
    };

    let filters = value
        .get("filters")
        .and_then(Value::as_object)
        .ok_or_else(|| ApiError::query_invalid("filters must be an object"))?;
    if filters.is_empty() {
        // API.md E1: reject accidental full dumps (at least one filter).
        return Err(ApiError::query_invalid(
            "at least one filter is required to prevent a full dump",
        ));
    }

    // Round-trip through the C2 parser so value/protocol validation lives in
    // one place. Values are percent-encoded to survive the `&`/`=` splitter.
    let mut parts = Vec::with_capacity(filters.len());
    for (key, filter_value) in filters {
        if !FILTER_KEYS.contains(&key.as_str()) {
            return Err(ApiError::query_invalid(format!(
                "Unknown filter key '{key}'. Allowed: {}",
                FILTER_KEYS.join(", ")
            )));
        }
        let text = match filter_value {
            Value::String(text) => text.clone(),
            Value::Number(number) => number.to_string(),
            Value::Bool(flag) => flag.to_string(),
            _ => {
                return Err(ApiError::query_invalid(format!(
                    "invalid filter value for {key}"
                )));
            }
        };
        if text.is_empty() {
            return Err(ApiError::query_invalid(format!(
                "empty filter value for {key}"
            )));
        }
        parts.push(format!("{key}={}", percent_encode(&text)));
    }
    let query = crate::history::parse_query(&parts.join("&"))?;
    if !any_filter_present(&query) {
        return Err(ApiError::query_invalid("at least one filter is required"));
    }
    Ok(ParsedRequest {
        scope,
        format,
        query,
    })
}

fn any_filter_present(q: &ConnectionsQuery) -> bool {
    q.app_id.is_some()
        || q.app_name.is_some()
        || q.open.is_some()
        || q.protocol.is_some()
        || q.interface_id.is_some()
        || q.since.is_some()
        || q.until.is_some()
        || q.remote_ip.is_some()
        || q.remote_host.is_some()
        || q.remote_port.is_some()
}

/// Percent-encode a filter value for the C2 query-string parser.
fn percent_encode(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for byte in text.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(byte as char);
            }
            other => {
                let _ = write!(out, "%{other:02X}");
            }
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Row generation
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct Generated {
    content: Vec<u8>,
    content_type: &'static str,
    filename: String,
    rows: i64,
}

async fn generate(
    db: &SqlitePool,
    parsed: &ParsedRequest,
    now: u64,
) -> Result<Generated, ApiError> {
    let (columns, rows) = match parsed.scope {
        Scope::Connections => connections_rows(db, &parsed.query).await?,
        Scope::UsageHourly => usage_rows(db, &parsed.query, 3_600).await?,
        Scope::UsageDaily => usage_rows(db, &parsed.query, 86_400).await?,
    };
    let content = match parsed.format {
        Format::Csv => encode_csv(&columns, &rows),
        Format::Json => encode_json(&columns, &rows),
    };
    let date = utc_date(now);
    let filename = format!("netwatch-pro-export-{date}.{}", parsed.format.extension());
    Ok(Generated {
        content,
        content_type: parsed.format.content_type(),
        filename,
        rows: i64::try_from(rows.len()).unwrap_or(i64::MAX),
    })
}

async fn connections_rows(
    db: &SqlitePool,
    q: &ConnectionsQuery,
) -> Result<(Vec<&'static str>, Vec<Vec<Value>>), ApiError> {
    let mut builder = QueryBuilder::new(
        "SELECT id, app_id, interface_id, pid, process_name, protocol, local_ip, local_port, \
         remote_ip, remote_port, remote_host, bytes_up, bytes_down, packets_up, packets_down, \
         first_seen_at, last_seen_at, is_open FROM connections WHERE 1=1",
    );
    if let Some(app_id) = q.app_id {
        builder.push(" AND app_id = ").push_bind(app_id);
    }
    if let Some(name) = &q.app_name {
        builder
            .push(" AND app_id IN (SELECT id FROM apps WHERE name LIKE '%' || ")
            .push_bind(name.clone())
            .push(" || '%')");
    }
    if let Some(open) = q.open {
        builder.push(" AND is_open = ").push_bind(i64::from(open));
    }
    if let Some(protocol) = &q.protocol {
        builder.push(" AND protocol = ").push_bind(protocol.clone());
    }
    if let Some(interface_id) = q.interface_id {
        builder.push(" AND interface_id = ").push_bind(interface_id);
    }
    if let Some(since) = q.since {
        builder.push(" AND last_seen_at >= ").push_bind(since);
    }
    if let Some(until) = q.until {
        builder.push(" AND first_seen_at <= ").push_bind(until);
    }
    if let Some(remote_ip) = &q.remote_ip {
        builder
            .push(" AND remote_ip = ")
            .push_bind(remote_ip.clone());
    }
    if let Some(remote_host) = &q.remote_host {
        builder
            .push(" AND remote_host LIKE '%' || ")
            .push_bind(remote_host.clone())
            .push(" || '%'");
    }
    if let Some(remote_port) = q.remote_port {
        builder.push(" AND remote_port = ").push_bind(remote_port);
    }
    builder.push(" ORDER BY last_seen_at DESC, id DESC");

    let rows = builder
        .build()
        .fetch_all(db)
        .await
        .map_err(crate::history::db_error)?;
    let values = rows
        .iter()
        .map(|row| {
            vec![
                json!(row.get::<i64, _>("id")),
                json!(row.get::<i64, _>("app_id")),
                json!(row.get::<Option<i64>, _>("interface_id")),
                json!(row.get::<i64, _>("pid")),
                json!(row.get::<Option<String>, _>("process_name")),
                json!(row.get::<String, _>("protocol")),
                json!(row.get::<String, _>("local_ip")),
                json!(row.get::<i64, _>("local_port")),
                json!(row.get::<String, _>("remote_ip")),
                json!(row.get::<i64, _>("remote_port")),
                json!(row.get::<Option<String>, _>("remote_host")),
                json!(row.get::<i64, _>("bytes_up")),
                json!(row.get::<i64, _>("bytes_down")),
                json!(row.get::<i64, _>("packets_up")),
                json!(row.get::<i64, _>("packets_down")),
                json!(row.get::<i64, _>("first_seen_at")),
                json!(row.get::<i64, _>("last_seen_at")),
                json!(row.get::<i64, _>("is_open")),
            ]
        })
        .collect();
    Ok((CONNECTIONS_COLUMNS.to_vec(), values))
}

/// Usage scopes aggregate the 15-minute rollup into hour/day buckets. Only
/// `app_id`/`since`/`until` are meaningful on rollups; other filter keys are
/// accepted (C2 whitelist) but do not apply (they describe connection-level
/// fields absent from rollups).
async fn usage_rows(
    db: &SqlitePool,
    q: &ConnectionsQuery,
    divisor: i64,
) -> Result<(Vec<&'static str>, Vec<Vec<Value>>), ApiError> {
    let mut builder = QueryBuilder::new(format!(
        "SELECT app_id, (bucket_start / {divisor}) * {divisor} AS bucket, \
         SUM(bytes_up) AS bytes_up, SUM(bytes_down) AS bytes_down, \
         SUM(connection_count) AS connection_count FROM usage_rollup_15m WHERE 1=1"
    ));
    if let Some(app_id) = q.app_id {
        builder.push(" AND app_id = ").push_bind(app_id);
    }
    if let Some(since) = q.since {
        builder.push(" AND bucket_start >= ").push_bind(since);
    }
    if let Some(until) = q.until {
        builder.push(" AND bucket_start <= ").push_bind(until);
    }
    builder.push(" GROUP BY app_id, bucket ORDER BY bucket DESC, app_id");

    let rows = builder
        .build()
        .fetch_all(db)
        .await
        .map_err(crate::history::db_error)?;
    let values = rows
        .iter()
        .map(|row| {
            vec![
                json!(row.get::<i64, _>("app_id")),
                json!(row.get::<i64, _>("bucket")),
                json!(row.get::<i64, _>("bytes_up")),
                json!(row.get::<i64, _>("bytes_down")),
                json!(row.get::<i64, _>("connection_count")),
            ]
        })
        .collect();
    Ok((USAGE_COLUMNS.to_vec(), values))
}

// ---------------------------------------------------------------------------
// Encoding
// ---------------------------------------------------------------------------

fn encode_csv(columns: &[&str], rows: &[Vec<Value>]) -> Vec<u8> {
    let mut out = columns.join(",");
    out.push('\n');
    for row in rows {
        let cells: Vec<String> = row.iter().map(csv_cell).collect();
        out.push_str(&cells.join(","));
        out.push('\n');
    }
    out.into_bytes()
}

fn csv_cell(value: &Value) -> String {
    match value {
        Value::Null => String::new(),
        Value::Bool(flag) => flag.to_string(),
        Value::Number(number) => number.to_string(),
        Value::String(text) => csv_quote(text),
        other => csv_quote(&other.to_string()),
    }
}

fn csv_quote(text: &str) -> String {
    if text.chars().any(|ch| matches!(ch, ',' | '"' | '\n' | '\r')) {
        format!("\"{}\"", text.replace('"', "\"\""))
    } else {
        text.to_string()
    }
}

fn encode_json(columns: &[&str], rows: &[Vec<Value>]) -> Vec<u8> {
    let objects: Vec<Map<String, Value>> = rows
        .iter()
        .map(|row| {
            let mut object = Map::with_capacity(columns.len());
            for (column, value) in columns.iter().zip(row) {
                object.insert((*column).to_string(), value.clone());
            }
            object
        })
        .collect();
    serde_json::to_vec(&objects).unwrap_or_default()
}

/// UTC `YYYYMMDD` for the Content-Disposition filename, derived from the
/// caller-supplied epoch (no clock feature needed in the `chrono` dependency).
fn utc_date(epoch_s: u64) -> String {
    let seconds = i64::try_from(epoch_s).unwrap_or_default();
    chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, 0).map_or_else(
        || "00000000".to_string(),
        |stamp| stamp.format("%Y%m%d").to_string(),
    )
}

// ---------------------------------------------------------------------------
// Job registry + orchestration
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct Job {
    created_at: Instant,
    generated: Generated,
}

impl Job {
    fn is_expired(&self) -> bool {
        self.created_at.elapsed() >= TTL
    }
}

/// In-memory store of export jobs (API.md E2 "in-memory; flagged §10").
#[derive(Debug, Default)]
pub struct ExportRegistry {
    jobs: Mutex<HashMap<String, Job>>,
}

impl ExportRegistry {
    /// Create an empty in-memory job registry.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Store a generated file, purging expired jobs to bound memory.
    fn insert(&self, generated: Generated) -> String {
        let mut jobs = self
            .jobs
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        jobs.retain(|_, job| !job.is_expired());
        loop {
            let id = new_id();
            if !jobs.contains_key(&id) {
                jobs.insert(
                    id.clone(),
                    Job {
                        created_at: Instant::now(),
                        generated,
                    },
                );
                return id;
            }
        }
    }
}

fn new_id() -> String {
    let mut bytes = [0u8; 2];
    if getrandom::fill(&mut bytes).is_err() {
        // CSPRNG failure is a degraded path (ARCHITECTURE.md §7.1): a
        // monotonic fallback keeps the uniqueness loop in `insert` finite.
        static FALLBACK: AtomicU64 = AtomicU64::new(0);
        let sequence = FALLBACK.fetch_add(1, Ordering::Relaxed);
        return format!("exp_fb{sequence:016x}");
    }
    format!("exp_{:02x}{:02x}", bytes[0], bytes[1])
}

/// E1 response payload.
#[derive(Debug, Serialize)]
pub struct CreateResponse {
    /// Opaque job id.
    pub id: String,
    /// Creation always reports `queued`; generation is synchronous so E2
    /// immediately reports `done` (API.md E1/E2).
    pub state: &'static str,
    /// Seconds until the job expires (600).
    pub expires_in_s: u64,
    /// Exact number of rows in the generated file.
    pub estimated_rows: i64,
}

/// E2 response payload.
#[derive(Debug, Serialize)]
pub struct StatusResponse {
    /// Opaque job id.
    pub id: String,
    /// One of `queued|running|done|expired` (API.md E2).
    pub state: String,
    /// Number of exported rows once complete.
    pub rows: i64,
    /// Size of the generated file in bytes.
    pub size_bytes: i64,
}

/// E3 response payload (headers + body) built by the route handler.
#[derive(Debug)]
pub struct Content {
    /// MIME type for the `Content-Type` header.
    pub content_type: &'static str,
    /// Attachment filename for `Content-Disposition`.
    pub filename: String,
    /// Generated file bytes.
    pub body: Vec<u8>,
}

/// Create an export job: parse → Pro gate → rate limit → generate → store.
///
/// # Errors
///
/// `QUERY_INVALID` for bad requests, `EXPORT_PRO_REQUIRED` for free tier,
/// `RATE_LIMITED` on the 6th creation in a minute, and `DB_ERROR` for SQLite
/// failures (API.md E1 §2.3 / §1.5).
pub async fn create_job(
    db: &SqlitePool,
    registry: &ExportRegistry,
    create_limiter: &RateLimiter,
    body: &[u8],
    now: u64,
) -> Result<CreateResponse, ApiError> {
    let parsed = parse_request(body)?;
    if !crate::license::is_pro(db).await? {
        return Err(ApiError::new(
            ErrorCode::ExportProRequired,
            axum::http::StatusCode::FORBIDDEN,
            "CSV/JSON export requires Pro",
        ));
    }
    create_limiter
        .try_acquire()
        .map_err(ApiError::rate_limited)?;
    let generated = generate(db, &parsed, now).await?;
    let estimated_rows = generated.rows;
    let id = registry.insert(generated);
    Ok(CreateResponse {
        id,
        state: "queued",
        expires_in_s: TTL.as_secs(),
        estimated_rows,
    })
}

/// E2 — job status. Expired jobs remain observable with `state:"expired"`
/// (the documented E2 state set) but carry no content.
///
/// # Errors
///
/// `NOT_FOUND` when no such job exists.
pub fn job_status(registry: &ExportRegistry, id: &str) -> Result<StatusResponse, ApiError> {
    let jobs = registry
        .jobs
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let job = jobs.get(id).ok_or_else(job_not_found)?;
    if job.is_expired() {
        return Ok(StatusResponse {
            id: id.to_string(),
            state: "expired".to_string(),
            rows: 0,
            size_bytes: 0,
        });
    }
    Ok(StatusResponse {
        id: id.to_string(),
        state: "done".to_string(),
        rows: job.generated.rows,
        size_bytes: i64::try_from(job.generated.content.len()).unwrap_or(i64::MAX),
    })
}

/// E3 — the generated file. Pro is not re-checked here: jobs created while Pro
/// remain downloadable after deactivation (FEATURES.md F9 grace edge case).
///
/// # Errors
///
/// `NOT_FOUND` when the job is unknown or expired; `RATE_LIMITED` after 10
/// downloads in a minute (API.md §1.5).
pub fn job_content(
    registry: &ExportRegistry,
    download_limiter: &RateLimiter,
    id: &str,
) -> Result<Content, ApiError> {
    download_limiter
        .try_acquire()
        .map_err(ApiError::rate_limited)?;
    let jobs = registry
        .jobs
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let job = jobs.get(id).ok_or_else(job_not_found)?;
    if job.is_expired() {
        return Err(ApiError::new(
            ErrorCode::NotFound,
            axum::http::StatusCode::NOT_FOUND,
            "Export job has expired",
        ));
    }
    Ok(Content {
        content_type: job.generated.content_type,
        filename: job.generated.filename.clone(),
        body: job.generated.content.clone(),
    })
}

fn job_not_found() -> ApiError {
    ApiError::new(
        ErrorCode::NotFound,
        axum::http::StatusCode::NOT_FOUND,
        "Export job not found",
    )
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, clippy::expect_used)] // tests, not daemon paths

    use super::*;
    use sqlx::sqlite::{SqliteConnectOptions, SqlitePoolOptions};

    const NOW: u64 = 1_731_565_200; // 2024-11-14T13:00:00Z

    async fn seeded_db() -> SqlitePool {
        let pool = SqlitePoolOptions::new()
            .max_connections(1)
            .connect_with(SqliteConnectOptions::new().in_memory(true))
            .await
            .unwrap();
        sqlx::query(
            "CREATE TABLE apps (id INTEGER PRIMARY KEY, name TEXT NOT NULL,
                first_seen_at INTEGER NOT NULL DEFAULT 0, last_seen_at INTEGER NOT NULL DEFAULT 0)",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "CREATE TABLE connections (
                id INTEGER PRIMARY KEY AUTOINCREMENT, app_id INTEGER NOT NULL,
                pid INTEGER NOT NULL, process_name TEXT, protocol TEXT NOT NULL,
                local_ip TEXT NOT NULL, local_port INTEGER NOT NULL,
                remote_ip TEXT NOT NULL, remote_port INTEGER NOT NULL, remote_host TEXT,
                bytes_up INTEGER NOT NULL DEFAULT 0, bytes_down INTEGER NOT NULL DEFAULT 0,
                packets_up INTEGER NOT NULL DEFAULT 0, packets_down INTEGER NOT NULL DEFAULT 0,
                first_seen_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL,
                is_open INTEGER NOT NULL DEFAULT 0, interface_id INTEGER)",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "CREATE TABLE usage_rollup_15m (
                app_id INTEGER NOT NULL, bucket_start INTEGER NOT NULL,
                bytes_up INTEGER NOT NULL DEFAULT 0, bytes_down INTEGER NOT NULL DEFAULT 0,
                connection_count INTEGER NOT NULL DEFAULT 0, interfaces_mask TEXT,
                PRIMARY KEY (app_id, bucket_start))",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query("INSERT INTO apps (id, name) VALUES (1, 'Firefox')")
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query(
            "INSERT INTO connections (app_id, pid, process_name, protocol, local_ip, local_port,
                remote_ip, remote_port, remote_host, bytes_up, bytes_down, packets_up, packets_down,
                first_seen_at, last_seen_at, is_open, interface_id)
             VALUES (1, 42, 'firefox', 'tcp', '10.0.0.2', 50000, '198.51.100.1', 443,
                'example.com', 100, 200, 3, 4, 1733165200, 1733170600, 0, NULL)",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO usage_rollup_15m (app_id, bucket_start, bytes_up, bytes_down, connection_count)
             VALUES (1, 1733165100, 100, 200, 3), (1, 1733166000, 50, 60, 1)",
        )
        .execute(&pool)
        .await
        .unwrap();
        pool
    }

    fn parse(body: &str) -> ParsedRequest {
        parse_request(body.as_bytes()).unwrap()
    }

    #[test]
    fn parse_request_rejects_bad_shapes() {
        for body in [
            "not json",
            r#"{"scope":"bogus","format":"csv","filters":{"app_id":1}}"#,
            r#"{"scope":"connections","format":"xml","filters":{"app_id":1}}"#,
            r#"{"scope":"connections","format":"csv","filters":{}}"#,
            r#"{"scope":"connections","format":"csv","filters":{"bogus":1}}"#,
            r#"{"scope":"connections","format":"csv","filters":{"protocol":"sctp"}}"#,
        ] {
            assert!(
                parse_request(body.as_bytes()).is_err(),
                "body should be rejected: {body}"
            );
        }
    }

    #[test]
    fn parse_request_accepts_c2_whitelist() {
        let parsed = parse(
            r#"{"scope":"connections","format":"json","filters":{"app_id":1,"since":1733165200,"until":1733170600}}"#,
        );
        assert_eq!(parsed.scope, Scope::Connections);
        assert_eq!(parsed.format, Format::Json);
        assert_eq!(parsed.query.app_id, Some(1));
        assert_eq!(parsed.query.since, Some(1_733_165_200));
    }

    #[test]
    fn csv_escapes_special_characters() {
        assert_eq!(csv_quote("plain"), "plain");
        assert_eq!(csv_quote("a,b"), "\"a,b\"");
        assert_eq!(csv_quote("a\"b"), "\"a\"\"b\"");
        assert_eq!(csv_quote("line\nbreak"), "\"line\nbreak\"");
    }

    #[tokio::test]
    async fn connections_export_filters_and_encodes() {
        let db = seeded_db().await;
        let csv = parse(r#"{"scope":"connections","format":"csv","filters":{"app_id":1}}"#);
        let generated = generate(&db, &csv, NOW).await.unwrap();
        let text = String::from_utf8(generated.content.clone()).unwrap();
        assert!(text.starts_with("id,app_id,interface_id,"));
        assert!(text.contains("198.51.100.1"));
        assert!(text.contains("example.com"));
        assert_eq!(generated.rows, 1);
        assert_eq!(generated.filename, "netwatch-pro-export-20241114.csv");

        // A filter that matches nothing yields a header-only CSV.
        let none = parse(r#"{"scope":"connections","format":"csv","filters":{"app_id":999}}"#);
        let empty = generate(&db, &none, NOW).await.unwrap();
        assert_eq!(empty.rows, 0);
        assert_eq!(String::from_utf8(empty.content).unwrap().lines().count(), 1);
    }

    #[tokio::test]
    async fn json_export_has_keyed_objects() {
        let db = seeded_db().await;
        let parsed = parse(r#"{"scope":"connections","format":"json","filters":{"app_id":1}}"#);
        let generated = generate(&db, &parsed, NOW).await.unwrap();
        let rows: Value = serde_json::from_slice(&generated.content).unwrap();
        let rows = rows.as_array().unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0]["remote_ip"], "198.51.100.1");
        assert_eq!(rows[0]["bytes_down"], 200);
        assert!(rows[0]["interface_id"].is_null());
        assert_eq!(generated.content_type, "application/json");
    }

    #[tokio::test]
    async fn usage_scopes_aggregate_rollups() {
        let db = seeded_db().await;
        let daily = parse(r#"{"scope":"usage_daily","format":"json","filters":{"app_id":1}}"#);
        let generated = generate(&db, &daily, NOW).await.unwrap();
        let rows: Value = serde_json::from_slice(&generated.content).unwrap();
        let rows = rows.as_array().unwrap();
        assert_eq!(rows.len(), 1, "two 15m buckets in one UTC day");
        assert_eq!(rows[0]["bytes_up"], 150);
        assert_eq!(rows[0]["connection_count"], 4);
        assert_eq!(generated.filename, "netwatch-pro-export-20241114.json");
    }

    #[test]
    fn expired_job_is_observable_but_not_downloadable() {
        let registry = ExportRegistry::new();
        let limiter = RateLimiter::new(10, Duration::from_secs(60));
        let id = "exp_expired".to_string();
        {
            let mut jobs = registry.jobs.lock().unwrap();
            jobs.insert(
                id.clone(),
                Job {
                    created_at: Instant::now()
                        .checked_sub(TTL + Duration::from_secs(1))
                        .unwrap(),
                    generated: Generated {
                        content: b"old".to_vec(),
                        content_type: "text/csv",
                        filename: "old.csv".to_string(),
                        rows: 1,
                    },
                },
            );
        }
        let status = job_status(&registry, &id).unwrap();
        assert_eq!(status.state, "expired");
        assert_eq!(status.rows, 0);
        assert_eq!(
            job_content(&registry, &limiter, &id).unwrap_err().code(),
            ErrorCode::NotFound
        );
        assert_eq!(
            job_status(&registry, "exp_missing").unwrap_err().code(),
            ErrorCode::NotFound
        );
    }
}
